-card p{color:#b6c1b6;font-size:13px;line-height:1.8;margin:0 0 23px}.play-button{border:0;background:var(--lime);color:#10221a;font:800 12px 'DM Sans';letter-spacing:1.6px;height:46px;padding:0 18px;min-width:158px;display:flex;align-items:center;justify-content:space-between;gap:20px;cursor:pointer;transition:transform .15s,background .15s}.play-button:hover{background:#ddff8c;transform:translateY(-2px)}.play-button span{font-size:18px}.intro-meta{display:flex;gap:9px;align-items:center;margin-top:22px;color:#aab7ad;font-size:9px;font-weight:700;letter-spacing:1.2px}.intro-meta b{color:#58685d}.overlay-pitch-stamp{position:absolute;bottom:22px;right:26px;font-size:9px;letter-spacing:2px;color:#c5d1c599}.overlay-pitch-stamp span{color:var(--lime);padding:0 7px}.pause-badge{display:none;position:absolute;z-index:5;left:50%;top:50%;transform:translate(-50%,-50%);padding:13px 22px;background:#081713e8;border:1px solid #ffffff2a;font:700 13px 'Barlow Condensed';letter-spacing:2px}.pause-badge span{color:var(--lime);margin-right:8px}.pause-badge.show{display:block}.bottom-bar{min-height:44px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line);padding:0 2px 12px}.controls{display:flex;align-items:center;gap:12px}.controls>i{height:15px;width:1px;background:#ffffff1a}.control-item{display:flex;align-items:center;gap:4px;color:#9eaca2;font-size:9px;letter-spacing:.65px;font-weight:700}.control-item span{margin-left:5px}kbd{font:700 9px 'DM Sans';padding:4px 5px;min-width:20px;text-align:center;color:#e4e9e1;background:#172a25;border:1px solid #ffffff19;border-radius:3px;box-shadow:0 2px 0 #020907}.match-note{display:flex;align-items:center;gap:8px;font-size:9px;letter-spacing:1.1px;color:#8e9e93;font-weight:700;white-space:nowrap}.status-pip{width:6px;height:6px}.below-game{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:1px}.tip{display:flex;align-items:flex-start;gap:12px;padding:11px 4px}.tip-icon{color:var(--lime);font-size:17px;line-height:1}.tip strong{font:700 11px 'Barlow Condensed';letter-spacing:1.3px}.tip p{font-size:10px;color:#85968b;line-height:1.6;margin:4px 0 0}.tip kbd{font-size:8px;padding:2px 4px}.mobile-controls{display:none;position:absolute;z-index:4;bottom:16px;left:16px;right:16px;justify-content:space-between;align-items:flex-end;pointer-events:none}.mobile-controls button{pointer-events:auto;color:#fff;background:#071b19b8;border:1px solid #ffffff45;backdrop-filter:blur(5px);touch-action:none}.dpad>button,.dpad div button{width:40px;height:40px;border-radius:9px;font-size:12px}.dpad div{display:flex;gap:5px;margin-top:5px}.mobile-actions{display:flex;gap:7px;align-items:flex-end}.mobile-actions button{width:49px;height:49px;border-radius:50%;font:700 8px 'DM Sans';letter-spacing:.4px}.mobile-actions button[data-action=shoot]{width:59px;height:59px;color:#10221a;background:var(--lime);border-color:#e4ffb2}.mobile-actions button[data-action=skill]{margin-bottom:20px}.mobile-actions button[data-action=pass]{margin-bottom:7px}.mobile-actions button[data-action=steal]{margin-bottom:2px;color:#ffd2c9;border-color:#f36f5980}@media(max-width:850px){body{padding:12px}.game-shell{gap:9px}.game-frame{height:calc(100dvh - 190px);min-height:390px}.controls{gap:7px}.control-item{font-size:8px}.control-item span{margin-left:2px}.controls>i{margin:0 1px}.below-game{gap:8px}.tip{gap:7px}.tip p{font-size:9px}}@media(max-width:620px){body{padding:9px}.topbar{height:34px}.match-tag{font-size:8px;letter-spacing:1px}.brand{font-size:14px}.game-frame{height:calc(100dvh - 160px);min-height:380px;max-height:720px}.scoreboard{top:10px;min-width:285px;height:49px;gap:10px;padding:5px 11px}.score-team{font-size:9px}.score-center{min-width:72px;padding:0 9px}.score-center span{font-size:19px}.match-overlay{padding:9%}.intro-card h1{font-size:66px}.intro-card p{font-size:11px}.controls{gap:5px;flex-wrap:wrap}.control-item{font-size:7px}.control-item span{display:none}.controls>i{height:12px}.bottom-bar{min-height:35px;padding-bottom:7px}.match-note{font-size:8px}.below-game{grid-template-columns:1fr;gap:0}.tip{padding:4px;display:none}.mobile-controls{display:flex}.overlay-pitch-stamp{font-size:8px;bottom:12px;right:13px}.bottom-bar .controls{max-width:70%}}@media(max-height:700px) and (min-width:621px){body{padding-top:10px;padding-bottom:10px}.game-shell{gap:8px}.game-frame{height:70vh;min-height:360px}.below-game{display:none}}
